    87	\begin{definition}[Line-point distributions]\label{def:line-point-dist}
    88		\lean{MIPStarRE.QPBT.LineKind, MIPStarRE.QPBT.LineDesc}
    89		\lean{MIPStarRE.QPBT.aLinePointDist, MIPStarRE.QPBT.dLinePointDist}
    90		\lean{MIPStarRE.QPBT.linePointDist}
